// Get screen by number (1-36)
function getScreenByNum(num) {
  return CRM_SCREENS.find(s => s.num === parseInt(num)) || CRM_SCREENS[0];
}

// Render Wireframe Screen Viewer
function renderWireframeScreenViewer(screenNum) {
  const screen = getScreenByNum(screenNum);
  const currentNum = screen.num;
  const prevNum = currentNum > 1 ? currentNum - 1 : 36;
  const nextNum = currentNum < 36 ? currentNum + 1 : 1;

  // Build dropdown options grouped by category
  let dropdownOptions = '';
  CRM_CATEGORIES.forEach(cat => {
    dropdownOptions += `<optgroup label="${cat.icon} ${cat.name}">`;
    const catScreens = CRM_SCREENS.filter(s => s.num >= cat.range[0] && s.num <= cat.range[1]);
    catScreens.forEach(s => {
      dropdownOptions += `<option value="${s.num}" ${s.num === currentNum ? 'selected' : ''}>Screen ${s.num}: ${s.title} [${s.role}]</option>`;
    });
    dropdownOptions += `</optgroup>`;
  });

  return `
    <div class="wireframe-screen-container">
      <!-- Screen Quick Switcher Navigation Bar -->
      <div class="screen-switcher-bar">
        <div style="display:flex; align-items:center; gap:12px; flex-wrap:wrap;">
          <span class="screen-badge-pill">
            <span>${screen.categoryIcon}</span>
            <span>${screen.categoryName}</span>
          </span>
          <span style="font-size:12px; color:var(--text-muted); font-weight:600;">
            Screen <strong>${currentNum}</strong> of 36
          </span>
        </div>

        <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap;">
          <select class="screen-select-dropdown" onchange="navigateToWireframeScreen(this.value)">
            ${dropdownOptions}
          </select>

          <button class="screen-nav-btn" onclick="navigateToWireframeScreen(${prevNum})" title="Previous Screen">
            ← Prev (${prevNum})
          </button>
          <button class="screen-nav-btn primary" onclick="navigateToWireframeScreen(${nextNum})" title="Next Screen">
            Next (${nextNum}) →
          </button>
        </div>
      </div>

      <!-- Exact Screen Wireframe Card -->
      <div class="screen" style="border: 2px solid #CBD5E1; border-radius: 16px; background:#FFFFFF; box-shadow:0 10px 30px rgba(0,0,0,0.06); overflow:hidden;">
        <div class="screen-header" style="background:#1E3A8A; color:white; padding:18px 24px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">
          <h3 style="font-size:20px; font-weight:800; display:flex; align-items:center; gap:10px; margin:0; color:white;">
            <span class="screen-num" style="background:white; color:#1E3A8A; width:34px; height:34px; border-radius:50%; display:inline-flex; align-items:center; justify-content:center; font-size:16px; font-weight:900;">${screen.num}</span>
            ${screen.title}
          </h3>
          <span class="role-badge" style="background:rgba(255,255,255,0.2); color:white; padding:6px 14px; border-radius:20px; font-size:12px; font-weight:700;">${screen.role}</span>
        </div>

        <div class="screen-body" style="padding:24px;">
          <!-- Purpose Description -->
          <div class="screen-desc" style="background:#F8FAFC; border-left:4px solid #3B82F6; padding:12px 18px; border-radius:6px; margin-bottom:20px; font-size:13.5px; color:#334155;">
            ${screen.desc}
          </div>

          <!-- Mockup Display -->
          <div class="mockup" style="background:#FFFFFF; border:1px solid #E2E8F0; border-radius:12px; padding:20px; margin-bottom:20px;">
            ${screen.mockup}
          </div>

          <!-- API & Database Note -->
          ${screen.apiNote ? `
            <div class="api-note" style="background:#F1F5F9; padding:10px 16px; border-radius:8px; font-family:monospace; font-size:12.5px; color:#0F172A; display:flex; align-items:center; gap:8px;">
              <span style="background:#10B981; color:white; padding:2px 8px; border-radius:4px; font-weight:700; font-size:11px;">API</span>
              <span>${screen.apiNote}</span>
            </div>
          ` : ''}
        </div>
      </div>
    </div>
  `;
}


// Interactive tab switching for wireframe mockups
document.addEventListener('click', function(e) {
  const tab = e.target.closest('.mock-tab');
  if (tab && tab.parentElement) {
    const siblings = tab.parentElement.querySelectorAll('.mock-tab');
    siblings.forEach(s => s.classList.remove('active'));
    tab.classList.add('active');
  }
});
